preConditionHook:
// BarsSinceEntry is 0 on the fill bar and never a -1 sentinel (VERIFIED), so
// BarsSinceEntry + 1 addresses the SIGNAL bar: the fill bar's predecessor at 0,
// the bar before that at 1. EasyLanguage does not short-circuit its AND
// (EL_LogicalEval_Probe.txt), so the twin cannot put that subscript in the
// condition -- it would reach back BarsSinceEntry + 1 bars on EVERY bar of an
// open position. Both twins clamp it here instead, in branching control flow,
// which keeps the deepest reference at 2 and changes nothing the condition can
// see: the rule only fires at BarsSinceEntry <= 1.
sigOffset = ctx.BarsSinceEntry() + 1;
if (sigOffset > 2) sigOffset = 2;
sigLow = low[sigOffset];
sigHigh = high[sigOffset];
